package com.worldsplitter;

import java.util.ArrayList;
import java.util.List;

/**
 * Pure, side-effect free helpers that decide which worlds belong to which person.
 * <p>
 * Both allocation strategies guarantee two things the user asked for:
 * <ul>
 *     <li>every person's worlds are a single consecutive run from the sorted pool
 *     (never e.g. 302 then 360 for the same person)</li>
 *     <li>every world in the pool ends up assigned to exactly one person, with no gaps,
 *     no matter how the group size changes</li>
 * </ul>
 */
final class WorldAllocator
{
	private WorldAllocator()
	{
	}

	/**
	 * Fixed-size allocation used in "solo" mode: each person gets exactly {@code worldsPerPerson}
	 * consecutive worlds from the sorted pool. If the pool is smaller than
	 * {@code worldsPerPerson * totalPeople} the last people may receive fewer worlds (or none).
	 *
	 * @param sortedPool     ascending, deduplicated list of eligible world numbers
	 * @param totalPeople    how many people are splitting the pool
	 * @param worldsPerPerson how many worlds each person should receive
	 * @param position1Based which person we want the block for, 1 = first
	 * @return the consecutive list of worlds assigned to that person (never null, may be empty)
	 */
	static List<Integer> allocateFixedSize(
		List<Integer> sortedPool,
		int totalPeople,
		int worldsPerPerson,
		int position1Based)
	{
		if (sortedPool.isEmpty() || totalPeople < 1 || worldsPerPerson < 1
			|| position1Based < 1 || position1Based > totalPeople)
		{
			return new ArrayList<>();
		}

		int startIndex = (position1Based - 1) * worldsPerPerson;
		if (startIndex >= sortedPool.size())
		{
			return new ArrayList<>();
		}

		int endIndexExclusive = Math.min(startIndex + worldsPerPerson, sortedPool.size());
		return new ArrayList<>(sortedPool.subList(startIndex, endIndexExclusive));
	}

	/**
	 * Even allocation used in "group" mode: the whole pool is divided as evenly as possible
	 * across {@code totalPeople}, with any remainder worlds handed one-each to the first
	 * few people, so that the entire pool stays covered whenever the group grows or shrinks.
	 *
	 * @param sortedPool     ascending, deduplicated list of eligible world numbers
	 * @param totalPeople    current number of people in the group
	 * @param index0Based    this person's zero-based index/order within the group
	 * @return the consecutive list of worlds assigned to that person (never null, may be empty)
	 */
	static List<Integer> allocateEven(List<Integer> sortedPool, int totalPeople, int index0Based)
	{
		if (sortedPool.isEmpty() || totalPeople < 1 || index0Based < 0 || index0Based >= totalPeople)
		{
			return new ArrayList<>();
		}

		int poolSize = sortedPool.size();
		int base = poolSize / totalPeople;
		int remainder = poolSize % totalPeople;

		int startIndex = index0Based * base + Math.min(index0Based, remainder);
		int mySize = base + (index0Based < remainder ? 1 : 0);
		int endIndexExclusive = Math.min(startIndex + mySize, poolSize);

		if (startIndex >= poolSize)
		{
			return new ArrayList<>();
		}

		return new ArrayList<>(sortedPool.subList(startIndex, endIndexExclusive));
	}
}

package com.worldsplitter;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.WorldUtil;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldResult;

@Slf4j
@PluginDescriptor(
	name = "World Splitter",
	description = "Splits eligible worlds into consecutive blocks and highlights your worlds",
	tags = {"world", "worlds", "split", "group", "hopper"}
)
public class WorldSplitterPlugin extends Plugin
{
	@Inject
	private WorldSplitterConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WorldSplitterOverlay overlay;

	@Inject
	private WorldService worldService;

	@Inject
	private GroupSyncClient groupSyncClient;

	@Inject
	private ScheduledExecutorService executor;

	private final AtomicBoolean groupActionInProgress = new AtomicBoolean();

	private WorldSplitterPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> heartbeatTask;
	private volatile Set<Integer> assignedWorlds = Collections.emptySet();
	private volatile List<List<Integer>> groupAssignments = Collections.emptyList();

	private volatile boolean inGroup;
	private volatile String groupCode;
	private volatile String memberId;
	private volatile int groupMemberIndex;
	private volatile int groupMemberCount = 1;
	private volatile String actionStatus = "";

	@Provides
	WorldSplitterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WorldSplitterConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new WorldSplitterPanel(this);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("World Splitter")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		if (isGroupSyncReady())
		{
			String savedCode = config.activeGroupCode();
			String savedMember = config.activeMemberId();
			if (!isBlank(savedCode) && !isBlank(savedMember))
			{
				groupCode = savedCode;
				memberId = savedMember;
				inGroup = true;
				actionStatus = "Restoring saved group...";
				startHeartbeat();
				executor.execute(this::doHeartbeat);
			}
		}

		recomputeAssignedWorlds();
	}

	@Override
	protected void shutDown()
	{
		stopHeartbeat();
		overlayManager.remove(overlay);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		panel = null;
		navButton = null;
		assignedWorlds = Collections.emptySet();
		groupAssignments = Collections.emptyList();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!WorldSplitterConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("enableGroupSync".equals(event.getKey()) && !config.enableGroupSync() && inGroup)
		{
			stopHeartbeat();
			clearLocalGroupState();
			actionStatus = "Group sync disabled";
		}
		recomputeAssignedWorlds();
		refreshPanel();
	}

	void createGroup()
	{
		runGroupAction("Creating group...", () ->
		{
			GroupSyncClient.GroupState state = groupSyncClient.createGroup(config.serverUrl());
			applyGroupState(state);
			actionStatus = "Group created";
		});
	}

	void joinGroup(String code)
	{
		final String requestedCode = code == null ? "" : code.trim();
		if (requestedCode.isEmpty())
		{
			actionStatus = "Enter a 6-character group code";
			refreshPanel();
			return;
		}

		runGroupAction("Joining group...", () ->
		{
			GroupSyncClient.GroupState state = groupSyncClient.joinGroup(
				config.serverUrl(), requestedCode);
			applyGroupState(state);
			actionStatus = "Group joined";
		});
	}

	void leaveGroup()
	{
		if (!groupActionInProgress.compareAndSet(false, true))
		{
			return;
		}

		stopHeartbeat();
		String codeSnapshot = groupCode;
		String memberSnapshot = memberId;
		clearLocalGroupState();
		actionStatus = "Leaving group...";
		refreshPanel();

		executor.execute(() ->
		{
			try
			{
				if (config.enableGroupSync()
					&& !isBlank(codeSnapshot)
					&& !isBlank(memberSnapshot))
				{
					groupSyncClient.leaveGroup(
						config.serverUrl(), codeSnapshot, memberSnapshot);
				}
				actionStatus = "Group left";
			}
			catch (Exception e)
			{
				log.debug("Failed to notify World Splitter server of group leave", e);
				actionStatus = "Group left locally";
			}
			finally
			{
				groupActionInProgress.set(false);
				refreshPanel();
			}
		});
	}

	boolean isInGroup()
	{
		return inGroup;
	}

	boolean isGroupActionInProgress()
	{
		return groupActionInProgress.get();
	}

	boolean isGroupSyncReady()
	{
		return config.enableGroupSync() && !isBlank(config.serverUrl());
	}

	String getActionStatus()
	{
		return actionStatus;
	}

	String getActiveGroupCode()
	{
		return groupCode == null ? "" : groupCode;
	}

	int getGroupMemberCount()
	{
		return groupMemberCount;
	}

	int getGroupMemberIndex()
	{
		return groupMemberIndex;
	}

	Set<Integer> getAssignedWorlds()
	{
		return assignedWorlds;
	}

	List<Integer> getAssignedWorldsSorted()
	{
		List<Integer> list = new ArrayList<>(assignedWorlds);
		Collections.sort(list);
		return list;
	}

	List<List<Integer>> getGroupAssignments()
	{
		return groupAssignments;
	}

	private void runGroupAction(String pendingMessage, CheckedRunnable action)
	{
		if (!isGroupSyncReady())
		{
			actionStatus = config.enableGroupSync()
				? "Set a sync server URL in the plugin settings"
				: "Enable group sync in the plugin settings";
			refreshPanel();
			return;
		}

		if (!groupActionInProgress.compareAndSet(false, true))
		{
			return;
		}

		actionStatus = pendingMessage;
		refreshPanel();
		executor.execute(() ->
		{
			try
			{
				action.run();
			}
			catch (Exception e)
			{
				log.warn("World Splitter group action failed", e);
				actionStatus = readableError(e);
			}
			finally
			{
				groupActionInProgress.set(false);
				refreshPanel();
			}
		});
	}

	private void applyGroupState(GroupSyncClient.GroupState state) throws Exception
	{
		if (!isGroupSyncReady())
		{
			throw new IllegalStateException("Group sync was disabled");
		}

		inGroup = true;
		groupCode = state.getCode();
		memberId = state.getMemberId();
		groupMemberIndex = state.getIndex();
		groupMemberCount = Math.max(1, state.getTotalMembers());
		persistGroupState();
		startHeartbeat();

		// create/join runs on the background executor, so compute the complete
		// group allocation before the action is reported as finished.
		recomputeAssignedWorldsNow();
	}

	private void clearLocalGroupState()
	{
		inGroup = false;
		groupCode = null;
		memberId = null;
		groupMemberIndex = 0;
		groupMemberCount = 1;
		groupAssignments = Collections.emptyList();
		persistGroupState();
		recomputeAssignedWorlds();
	}

	private void persistGroupState()
	{
		config.setActiveGroupCode(groupCode == null ? "" : groupCode);
		config.setActiveMemberId(memberId == null ? "" : memberId);
	}

	private void startHeartbeat()
	{
		stopHeartbeat();
		if (isGroupSyncReady() && inGroup)
		{
			heartbeatTask = executor.scheduleAtFixedRate(
				this::doHeartbeat, 20, 20, TimeUnit.SECONDS);
		}
	}

	private void stopHeartbeat()
	{
		if (heartbeatTask != null)
		{
			heartbeatTask.cancel(false);
			heartbeatTask = null;
		}
	}

	private void doHeartbeat()
	{
		String codeSnapshot = groupCode;
		String memberSnapshot = memberId;
		if (!isGroupSyncReady() || !inGroup
			|| isBlank(codeSnapshot) || isBlank(memberSnapshot))
		{
			return;
		}

		try
		{
			GroupSyncClient.GroupState state = groupSyncClient.heartbeat(
				config.serverUrl(), codeSnapshot, memberSnapshot);
			boolean changed = state.getIndex() != groupMemberIndex
				|| state.getTotalMembers() != groupMemberCount;
			groupMemberIndex = state.getIndex();
			groupMemberCount = Math.max(1, state.getTotalMembers());
			actionStatus = "Group connected";

			if (changed)
			{
				// Heartbeat already runs off the client thread. Recompute immediately
				// so the member count, ranges and highlighted worlds change together.
				recomputeAssignedWorldsNow();
			}
			else
			{
				refreshPanel();
			}
		}
		catch (Exception e)
		{
			log.debug("World Splitter heartbeat failed; it will retry", e);
			actionStatus = "Group sync unavailable; retrying";
			refreshPanel();
		}
	}

	private void recomputeAssignedWorlds()
	{
		executor.execute(this::recomputeAssignedWorldsNow);
	}

	private void recomputeAssignedWorldsNow()
	{
		List<Integer> pool = buildWorldPool();
		List<Integer> mine;

		if (inGroup)
		{
			int totalMembers = Math.max(1, groupMemberCount);
			int myIndex = Math.max(0, Math.min(groupMemberIndex, totalMembers - 1));
			List<List<Integer>> assignments = new ArrayList<>(totalMembers);

			for (int index = 0; index < totalMembers; index++)
			{
				List<Integer> allocation = WorldAllocator.allocateEven(pool, totalMembers, index);
				assignments.add(Collections.unmodifiableList(new ArrayList<>(allocation)));
			}

			groupAssignments = Collections.unmodifiableList(assignments);
			mine = assignments.get(myIndex);
		}
		else
		{
			groupAssignments = Collections.emptyList();
			mine = WorldAllocator.allocateFixedSize(
				pool,
				Math.max(1, config.totalPeople()),
				Math.max(1, config.worldsPerPerson()),
				Math.max(1, config.myPosition()));
		}

		assignedWorlds = Collections.unmodifiableSet(new LinkedHashSet<>(mine));
		refreshPanel();
	}

	private List<Integer> buildWorldPool()
	{
		List<Integer> pool = new ArrayList<>();
		List<World> worlds = null;

		try
		{
			WorldResult result = worldService.getWorlds();
			worlds = result == null ? null : result.getWorlds();
		}
		catch (Exception e)
		{
			log.debug("Failed to fetch the live world list", e);
		}

		if (worlds == null || worlds.isEmpty())
		{
			for (int world = config.worldPoolStart(); world <= config.worldPoolEnd(); world++)
			{
				pool.add(world);
			}
			return pool;
		}

		for (World world : worlds)
		{
			int id = world.getId();
			if (id < config.worldPoolStart() || id > config.worldPoolEnd())
			{
				continue;
			}

			Set<WorldType> worldTypes = WorldUtil.toWorldTypes(world.getTypes());
			boolean members = worldTypes.contains(WorldType.MEMBERS);
			boolean dangerous = worldTypes.contains(WorldType.PVP)
				|| worldTypes.contains(WorldType.HIGH_RISK)
				|| worldTypes.contains(WorldType.DEADMAN)
				|| worldTypes.contains(WorldType.LAST_MAN_STANDING)
				|| worldTypes.contains(WorldType.PVP_ARENA)
				|| worldTypes.contains(WorldType.TOURNAMENT_WORLD);

			if (dangerous && !config.includePvpWorlds())
			{
				continue;
			}
			if (members && !config.includeMembersWorlds())
			{
				continue;
			}
			if (!members && !config.includeF2pWorlds())
			{
				continue;
			}

			pool.add(id);
		}

		pool.sort(Comparator.naturalOrder());
		return pool;
	}

	private void refreshPanel()
	{
		WorldSplitterPanel currentPanel = panel;
		if (currentPanel != null)
		{
			currentPanel.refresh();
		}
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static String readableError(Exception e)
	{
		String message = e.getMessage();
		if (isBlank(message))
		{
			return "Group sync request failed";
		}
		return message.length() > 90 ? message.substring(0, 90) : message;
	}

	@FunctionalInterface
	private interface CheckedRunnable
	{
		void run() throws Exception;
	}
}

package com.worldsplitter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class WorldSplitterPanel extends PluginPanel
{
	private final WorldSplitterPlugin plugin;
	private final JLabel modeLabel = new JLabel();
	private final JLabel worldsLabel = new JLabel();
	private final JLabel groupInfoLabel = new JLabel();
	private final JLabel actionStatusLabel = new JLabel();
	private final JPanel assignmentsPanel = new JPanel();
	private final JPanel notInGroupPanel = new JPanel(new GridLayout(2, 1, 0, 6));
	private final JPanel inGroupPanel = new JPanel(new GridLayout(2, 1, 0, 6));
	private final JTextField joinCodeField = new JTextField();
	private final JButton createGroupButton = new JButton("Create group");
	private final JButton joinGroupButton = new JButton("Join group");
	private final JButton leaveGroupButton = new JButton("Leave group");
	private final JButton copyCodeButton = new JButton("Copy code");

	WorldSplitterPanel(WorldSplitterPlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));

		JLabel title = new JLabel("World Splitter");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setAlignmentX(CENTER_ALIGNMENT);
		content.add(title);
		content.add(Box.createRigidArea(new Dimension(0, 8)));

		modeLabel.setForeground(Color.LIGHT_GRAY);
		modeLabel.setAlignmentX(CENTER_ALIGNMENT);
		content.add(modeLabel);

		worldsLabel.setFont(FontManager.getRunescapeBoldFont());
		worldsLabel.setHorizontalAlignment(SwingConstants.CENTER);
		worldsLabel.setAlignmentX(CENTER_ALIGNMENT);
		content.add(Box.createRigidArea(new Dimension(0, 6)));
		content.add(worldsLabel);
		content.add(Box.createRigidArea(new Dimension(0, 10)));

		groupInfoLabel.setForeground(Color.LIGHT_GRAY);
		groupInfoLabel.setAlignmentX(CENTER_ALIGNMENT);
		groupInfoLabel.setHorizontalAlignment(SwingConstants.CENTER);
		content.add(groupInfoLabel);
		content.add(Box.createRigidArea(new Dimension(0, 8)));

		assignmentsPanel.setLayout(new BoxLayout(assignmentsPanel, BoxLayout.Y_AXIS));
		assignmentsPanel.setAlignmentX(CENTER_ALIGNMENT);
		content.add(assignmentsPanel);
		content.add(Box.createRigidArea(new Dimension(0, 8)));

		actionStatusLabel.setForeground(new Color(255, 190, 80));
		actionStatusLabel.setAlignmentX(CENTER_ALIGNMENT);
		actionStatusLabel.setHorizontalAlignment(SwingConstants.CENTER);
		content.add(actionStatusLabel);
		content.add(Box.createRigidArea(new Dimension(0, 8)));

		createGroupButton.addActionListener(e -> plugin.createGroup());

		JPanel joinRow = new JPanel(new BorderLayout(4, 0));
		joinCodeField.setColumns(8);
		joinRow.add(joinCodeField, BorderLayout.CENTER);
		joinRow.add(joinGroupButton, BorderLayout.EAST);
		joinGroupButton.addActionListener(e -> plugin.joinGroup(joinCodeField.getText()));

		leaveGroupButton.addActionListener(e -> plugin.leaveGroup());
		copyCodeButton.addActionListener(e -> copyGroupCode());

		notInGroupPanel.add(createGroupButton);
		notInGroupPanel.add(joinRow);

		JPanel copyRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		copyRow.add(copyCodeButton);
		inGroupPanel.add(copyRow);
		inGroupPanel.add(leaveGroupButton);

		JPanel groupControls = new JPanel();
		groupControls.setLayout(new BoxLayout(groupControls, BoxLayout.Y_AXIS));
		groupControls.add(notInGroupPanel);
		groupControls.add(inGroupPanel);
		content.add(groupControls);

		add(content, BorderLayout.NORTH);
		refresh();
	}

	void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}

		boolean inGroup = plugin.isInGroup();
		boolean busy = plugin.isGroupActionInProgress();
		boolean syncReady = plugin.isGroupSyncReady();
		notInGroupPanel.setVisible(!inGroup);
		inGroupPanel.setVisible(inGroup);
		assignmentsPanel.setVisible(inGroup);

		createGroupButton.setEnabled(syncReady && !busy);
		joinGroupButton.setEnabled(syncReady && !busy);
		joinCodeField.setEnabled(syncReady && !busy);
		leaveGroupButton.setEnabled(!busy);
		copyCodeButton.setEnabled(!busy && inGroup);

		if (inGroup)
		{
			modeLabel.setText("Group mode - code " + plugin.getActiveGroupCode());
			groupInfoLabel.setText(
				"<html><center>" + plugin.getGroupMemberCount()
					+ " people in group<br>you are #"
					+ (plugin.getGroupMemberIndex() + 1) + "</center></html>");
			updateGroupAssignments(plugin.getGroupAssignments(), plugin.getGroupMemberIndex());
		}
		else
		{
			modeLabel.setText("Solo mode");
			groupInfoLabel.setText(syncReady
				? "Create or join a group to sync worlds live"
				: "Enable group sync and set a server URL in settings");
			assignmentsPanel.removeAll();
		}

		String actionStatus = plugin.getActionStatus();
		actionStatusLabel.setText(actionStatus == null ? "" : actionStatus);
		updateWorldsLabel(plugin.getAssignedWorldsSorted());
		revalidate();
		repaint();
	}

	private void copyGroupCode()
	{
		String code = plugin.getActiveGroupCode();
		if (code != null && !code.isEmpty())
		{
			Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(code), null);
		}
	}

	private void updateGroupAssignments(List<List<Integer>> assignments, int myIndex)
	{
		assignmentsPanel.removeAll();

		if (assignments.isEmpty())
		{
			JLabel calculating = new JLabel("Calculating group ranges...");
			calculating.setForeground(Color.LIGHT_GRAY);
			calculating.setAlignmentX(CENTER_ALIGNMENT);
			assignmentsPanel.add(calculating);
			return;
		}

		for (int index = 0; index < assignments.size(); index++)
		{
			List<Integer> worlds = assignments.get(index);
			boolean mine = index == myIndex;

			JPanel card = new JPanel(new BorderLayout(6, 0));
			card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));
			card.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(mine ? new Color(255, 190, 80) : new Color(70, 70, 70)),
				BorderFactory.createEmptyBorder(6, 8, 6, 8)));

			JLabel memberLabel = new JLabel("#" + (index + 1) + (mine ? " (you)" : ""));
			memberLabel.setFont(FontManager.getRunescapeBoldFont());
			card.add(memberLabel, BorderLayout.WEST);

			JLabel rangeLabel = new JLabel(formatWorldRange(worlds));
			rangeLabel.setHorizontalAlignment(SwingConstants.RIGHT);
			card.add(rangeLabel, BorderLayout.CENTER);

			assignmentsPanel.add(card);
			if (index < assignments.size() - 1)
			{
				assignmentsPanel.add(Box.createRigidArea(new Dimension(0, 4)));
			}
		}
	}

	private void updateWorldsLabel(List<Integer> worlds)
	{
		if (worlds.isEmpty())
		{
			worldsLabel.setText("No worlds assigned");
		}
		else if (worlds.size() == 1)
		{
			worldsLabel.setText("World " + worlds.get(0));
		}
		else
		{
			worldsLabel.setText(
				"Worlds " + worlds.get(0) + " - " + worlds.get(worlds.size() - 1)
					+ " (" + worlds.size() + ")");
		}
	}

	private static String formatWorldRange(List<Integer> worlds)
	{
		if (worlds.isEmpty())
		{
			return "No worlds";
		}
		if (worlds.size() == 1)
		{
			return Integer.toString(worlds.get(0));
		}
		return worlds.get(0) + " - " + worlds.get(worlds.size() - 1)
			+ " (" + worlds.size() + ")";
	}
}

