package com.worldsplitter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Highlights assigned worlds in the in-game world switcher without covering the world list. */
class WorldSplitterOverlay extends Overlay
{
	private static final int HORIZONTAL_PADDING = 4;
	private static final int VERTICAL_PADDING = 2;
	private static final int FILL_ALPHA = 24;
	private static final int BORDER_ALPHA = 220;

	private final Client client;
	private final WorldSplitterPlugin plugin;
	private final WorldSplitterConfig config;

	@Inject
	private WorldSplitterOverlay(
			Client client,
			WorldSplitterPlugin plugin,
			WorldSplitterConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightEnabled())
		{
			return null;
		}

		Set<Integer> assigned = plugin.getAssignedWorlds();
		if (assigned.isEmpty())
		{
			return null;
		}

		Widget root = client.getWidget(InterfaceID.WORLDSWITCHER, 0);
		if (root == null || root.isHidden())
		{
			return null;
		}

		Rectangle rootBounds = root.getBounds();
		if (rootBounds == null || rootBounds.width <= 0 || rootBounds.height <= 0)
		{
			return null;
		}

		Color configured = config.highlightColor();
		Color fill = withAlpha(configured, FILL_ALPHA);
		Color border = withAlpha(configured, BORDER_ALPHA);

		Deque<Widget> stack = new ArrayDeque<>();
		stack.push(root);

		while (!stack.isEmpty())
		{
			Widget widget = stack.pop();
			if (widget == null || widget.isHidden())
			{
				continue;
			}

			Integer worldNumber = parseWorldNumber(widget.getText());
			if (worldNumber != null && assigned.contains(worldNumber))
			{
				highlightWorldNumber(graphics, widget, rootBounds, fill, border);
			}

			pushChildren(stack, widget.getDynamicChildren());
			pushChildren(stack, widget.getStaticChildren());
			pushChildren(stack, widget.getNestedChildren());
		}

		return null;
	}

	/**
	 * Highlight only the actual world-number widget.
	 *
	 * Do not expand to the parent widget: in the world switcher the parent can be
	 * a whole column/container, which creates the large solid bar that obscures
	 * the interface.
	 */
	private static void highlightWorldNumber(
			Graphics2D graphics,
			Widget widget,
			Rectangle rootBounds,
			Color fill,
			Color border)
	{
		Rectangle bounds = widget.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return;
		}

		Rectangle highlightBounds = new Rectangle(
				bounds.x - HORIZONTAL_PADDING,
				bounds.y - VERTICAL_PADDING,
				bounds.width + (HORIZONTAL_PADDING * 2),
				bounds.height + (VERTICAL_PADDING * 2)
		);

		Rectangle clipped = highlightBounds.intersection(rootBounds);
		if (clipped.isEmpty())
		{
			return;
		}

		graphics.setColor(fill);
		graphics.fillRect(clipped.x, clipped.y, clipped.width, clipped.height);

		graphics.setColor(border);
		graphics.drawRect(
				clipped.x,
				clipped.y,
				Math.max(0, clipped.width - 1),
				Math.max(0, clipped.height - 1)
		);
	}

	private static Color withAlpha(Color color, int alpha)
	{
		if (color == null)
		{
			return new Color(0, 255, 0, alpha);
		}

		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	private static void pushChildren(Deque<Widget> stack, Widget[] children)
	{
		if (children == null)
		{
			return;
		}

		for (Widget child : children)
		{
			if (child != null)
			{
				stack.push(child);
			}
		}
	}

	private static Integer parseWorldNumber(String text)
	{
		if (text == null || text.length() != 3)
		{
			return null;
		}

		for (int i = 0; i < text.length(); i++)
		{
			if (!Character.isDigit(text.charAt(i)))
			{
				return null;
			}
		}

		try
		{
			int value = Integer.parseInt(text);
			return value >= 300 && value < 1000 ? value : null;
		}
		catch (NumberFormatException ignored)
		{
			return null;
		}
	}
}

package com.worldsplitter;

import com.google.gson.Gson;
import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Blocking HTTP client for the optional self-hosted group synchronization server.
 * Callers must invoke these methods from RuneLite's background executor.
 */
@Singleton
class GroupSyncClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final Pattern GROUP_CODE = Pattern.compile("[A-HJ-NP-Z2-9]{6}");
	private static final Pattern MEMBER_ID = Pattern.compile("[a-f0-9]{32}");

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	GroupSyncClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	static class GroupState
	{
		private String code;
		private String memberId;
		private int index;
		private int totalMembers;

		String getCode()
		{
			return code;
		}

		String getMemberId()
		{
			return memberId;
		}

		int getIndex()
		{
			return index;
		}

		int getTotalMembers()
		{
			return totalMembers;
		}
	}

	GroupState createGroup(String serverUrl) throws IOException
	{
		Request request = new Request.Builder()
			.url(baseUrl(serverUrl) + "/api/groups")
			.post(RequestBody.create(JSON, "{}"))
			.build();

		return execute(request);
	}

	GroupState joinGroup(String serverUrl, String code) throws IOException
	{
		String normalizedCode = normalizeCode(code);
		Request request = new Request.Builder()
			.url(baseUrl(serverUrl) + "/api/groups/" + normalizedCode + "/join")
			.post(RequestBody.create(JSON, "{}"))
			.build();

		return execute(request);
	}

	GroupState heartbeat(String serverUrl, String code, String memberId) throws IOException
	{
		String normalizedCode = normalizeCode(code);
		String normalizedMemberId = normalizeMemberId(memberId);
		String body = gson.toJson(new MemberBody(normalizedMemberId));
		Request request = new Request.Builder()
			.url(baseUrl(serverUrl) + "/api/groups/" + normalizedCode + "/heartbeat")
			.post(RequestBody.create(JSON, body))
			.build();

		return execute(request);
	}

	void leaveGroup(String serverUrl, String code, String memberId) throws IOException
	{
		String normalizedCode = normalizeCode(code);
		String normalizedMemberId = normalizeMemberId(memberId);
		String body = gson.toJson(new MemberBody(normalizedMemberId));
		Request request = new Request.Builder()
			.url(baseUrl(serverUrl) + "/api/groups/" + normalizedCode + "/leave")
			.post(RequestBody.create(JSON, body))
			.build();

		try (Response response = okHttpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				throw new IOException("Sync server returned HTTP " + response.code());
			}
		}
	}

	private GroupState execute(Request request) throws IOException
	{
		try (Response response = okHttpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new IOException("Sync server returned HTTP " + response.code());
			}

			GroupState state = gson.fromJson(response.body().string(), GroupState.class);
			validateState(state);
			return state;
		}
	}

	private static String baseUrl(String serverUrl) throws IOException
	{
		String url = serverUrl == null ? "" : serverUrl.trim();
		while (url.endsWith("/"))
		{
			url = url.substring(0, url.length() - 1);
		}

		try
		{
			URI uri = new URI(url);
			String scheme = uri.getScheme();
			String host = uri.getHost();
			if (uri.getUserInfo() != null || uri.getQuery() != null || uri.getFragment() != null
				|| host == null || !("https".equalsIgnoreCase(scheme)
				|| "http".equalsIgnoreCase(scheme)))
			{
				throw new IOException("Invalid sync server URL");
			}

			boolean localHost = "localhost".equalsIgnoreCase(host)
				|| "127.0.0.1".equals(host)
				|| "::1".equals(host);
			if ("http".equalsIgnoreCase(scheme) && !localHost)
			{
				throw new IOException("Public sync servers must use HTTPS");
			}
		}
		catch (URISyntaxException e)
		{
			throw new IOException("Invalid sync server URL", e);
		}

		return url;
	}

	private static String normalizeCode(String code) throws IOException
	{
		String normalized = code == null ? "" : code.trim().toUpperCase(Locale.ROOT);
		if (!GROUP_CODE.matcher(normalized).matches())
		{
			throw new IOException("Group code must contain 6 valid characters");
		}
		return normalized;
	}

	private static String normalizeMemberId(String memberId) throws IOException
	{
		String normalized = memberId == null ? "" : memberId.trim().toLowerCase(Locale.ROOT);
		if (!MEMBER_ID.matcher(normalized).matches())
		{
			throw new IOException("Invalid member id");
		}
		return normalized;
	}

	private static void validateState(GroupState state) throws IOException
	{
		if (state == null)
		{
			throw new IOException("Sync server returned an empty response");
		}
		state.code = normalizeCode(state.code);
		state.memberId = normalizeMemberId(state.memberId);
		if (state.totalMembers < 1 || state.index < 0 || state.index >= state.totalMembers)
		{
			throw new IOException("Sync server returned invalid group state");
		}
	}

	private static class MemberBody
	{
		private final String memberId;

		private MemberBody(String memberId)
		{
			this.memberId = memberId;
		}
	}
}
